end;
$function$

CREATE OR REPLACE FUNCTION public.request_activity_artifact_deletion(target_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform 1 from public.activity_artifacts where id=target_id and availability='accepted' for update;
  if not found then raise exception 'artifact is not accepted or does not exist'; end if;
  update public.activity_segments set source_artifact_id=null,source_session_index=null,source_message_index=null
    where source_artifact_id=target_id;
  update public.activity_file_ingestions set artifact_id=null,status='failed',claim_token=null,lease_expires_at=null,
    uploaded_at=null,
    staging_cleanup_pending=false,staging_cleanup_error=null,
    failed_at=coalesce(failed_at,now()),last_error_code='artifact_deletion_requested',
    last_error_message='Accepted source artifact entered controlled deletion',updated_at=now()
    where artifact_id=target_id;
  delete from public.activity_artifact_links where artifact_id=target_id;
  perform set_config('gradientpeak.artifact_lifecycle_authorized','on',true);
  update public.activity_artifacts set availability='deletion_pending',deletion_requested_at=now()
  where id=target_id and availability='accepted';
end $function$

CREATE OR REPLACE FUNCTION public.switch_activity_source_artifact(target_activity_id uuid, target_artifact_id uuid, target_profile_id uuid, target_provider_revision text DEFAULT NULL::text)
 RETURNS activity_artifact_links
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare inserted public.activity_artifact_links;
begin
  perform 1 from public.activity_artifacts
  where id=target_artifact_id and profile_id=target_profile_id and availability='accepted'
  for update;
  if not found then raise exception 'accepted artifact/profile not found'; end if;
  perform 1 from public.activities where id=target_activity_id and profile_id=target_profile_id for update;
  if not found then raise exception 'activity/profile not found'; end if;
  update public.activity_artifact_links set is_current=false
    where activity_id=target_activity_id and role='source' and is_current;
  insert into public.activity_artifact_links(activity_id,artifact_id,profile_id,role,ordinal,is_current,provider_revision)
  values(target_activity_id,target_artifact_id,target_profile_id,'source',
    coalesce((select max(ordinal)+1 from public.activity_artifact_links where activity_id=target_activity_id and role='source'),0),
    true,target_provider_revision) returning * into inserted;
  return inserted;
end $function$

CREATE OR REPLACE FUNCTION public.validate_activity_effort_segment_range()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare segment_record record;
begin
  if new.activity_id is null then return new; end if;
  select start_offset_ms,end_offset_ms,activity_category into segment_record from public.activity_segments
    where id=new.segment_id and activity_id=new.activity_id and profile_id=new.profile_id;
  if not found or segment_record.activity_category<>new.activity_category
    or new.start_offset is null or new.start_offset*1000<segment_record.start_offset_ms
    or (new.start_offset+new.duration_seconds)*1000>segment_record.end_offset_ms then
    raise exception 'activity effort must be contained by its matching-category segment';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_activity_segment_set(target_activity_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  parent_record record;
  segment_count integer;
  max_ordinal integer;
  summed_active bigint;
  summed_moving bigint;
  complete_count integer;
begin
  select elapsed_ms, active_ms, moving_ms,timing_coverage into parent_record
  from public.activities where id = target_activity_id;
  if not found then return; end if;

  select count(*), max(ordinal), sum(active_ms), sum(moving_ms),
    count(*) filter(where timing_coverage='complete' and active_ms is not null and moving_ms is not null)
    into segment_count, max_ordinal, summed_active, summed_moving,complete_count
  from public.activity_segments where activity_id = target_activity_id;
  if segment_count = 0 or max_ordinal <> segment_count - 1 then
    raise exception 'activity % segment ordinals must be contiguous from zero', target_activity_id;
  end if;
  if exists (select 1 from public.activity_segments where activity_id = target_activity_id and end_offset_ms > parent_record.elapsed_ms) then
    raise exception 'activity % segment exceeds parent elapsed bounds', target_activity_id;
  end if;
  if exists (
    select 1 from public.activity_segments s
    left join public.activity_segments p on p.activity_id=s.activity_id and p.ordinal=s.ordinal-1
    left join public.activity_segments n on n.activity_id=s.activity_id and n.ordinal=s.ordinal+1
    where s.activity_id=target_activity_id and s.role='transition'
      and (p.role is distinct from 'activity' or n.role is distinct from 'activity')
  ) then raise exception 'activity % transition must be between activity segments', target_activity_id; end if;
  if exists (
    select 1 from public.activity_segments s join public.activity_segments n
      on n.activity_id=s.activity_id and n.ordinal=s.ordinal+1
    where s.activity_id=target_activity_id and s.role='rest' and n.role='rest'
  ) then raise exception 'activity % has consecutive rest segments', target_activity_id; end if;
  if parent_record.timing_coverage='complete' then
    if complete_count<>segment_count then
      raise exception 'activity % complete parent requires complete timing for every segment',target_activity_id;
    end if;
    if parent_record.active_ms is distinct from summed_active or parent_record.moving_ms is distinct from summed_moving then
      raise exception 'activity % complete timing does not reconcile with segments',target_activity_id;
    end if;
  elsif parent_record.active_ms is not null or parent_record.moving_ms is not null then
    raise exception 'activity % partial/unavailable parent timing totals must be null',target_activity_id;
  end if;
  if exists (
    select 1 from public.activity_segments s
    where s.activity_id=target_activity_id
       and (s.summary->>'version' is distinct from s.summary_version::text
         or s.summary#>>'{timing,timingCoverage}' is distinct from s.timing_coverage
         or (s.summary#>>'{timing,activeMs}')::bigint is distinct from s.active_ms
         or (s.summary#>>'{timing,movingMs}')::bigint is distinct from s.moving_ms)
  ) then raise exception 'activity % segment summary timing/version mismatch', target_activity_id; end if;
end $function$

CREATE OR REPLACE FUNCTION public.validate_consent_supersession()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  consent_row public.athlete_data_sharing_consents%ROWTYPE;
  successor_row public.athlete_data_sharing_consents%ROWTYPE;
BEGIN
  SELECT * INTO consent_row FROM public.athlete_data_sharing_consents WHERE id = NEW.id;
  IF consent_row.superseded_by_consent_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF consent_row.superseded_by_consent_id = consent_row.id OR consent_row.ended_at IS NULL THEN
    RAISE EXCEPTION 'a consent successor requires an ended predecessor and cannot reference itself';
  END IF;
  SELECT * INTO successor_row FROM public.athlete_data_sharing_consents WHERE id = consent_row.superseded_by_consent_id;
  IF successor_row.ended_at IS NOT NULL THEN
    RAISE EXCEPTION 'consent successor must be current when linked';
  END IF;
  IF successor_row.granted_at < consent_row.granted_at OR consent_row.ended_at > successor_row.granted_at THEN
    RAISE EXCEPTION 'consent successor chronology is invalid';
  END IF;
  IF EXISTS (
    WITH RECURSIVE consent_chain(id, successor_id, path, cycle) AS (
      SELECT c.id, c.superseded_by_consent_id, ARRAY[c.id], false
      FROM public.athlete_data_sharing_consents c
      WHERE c.id = consent_row.id
      UNION ALL
      SELECT next_consent.id,
             next_consent.superseded_by_consent_id,
             consent_chain.path || next_consent.id,
             next_consent.id = ANY(consent_chain.path)
      FROM consent_chain
      JOIN public.athlete_data_sharing_consents next_consent ON next_consent.id = consent_chain.successor_id
      WHERE consent_chain.successor_id IS NOT NULL AND NOT consent_chain.cycle
    )
    SELECT 1 FROM consent_chain WHERE cycle
  ) THEN
    RAISE EXCEPTION 'consent supersession cannot contain a cycle';
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.validate_performance_calibration_model_inputs()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  evidence_id_to_validate uuid;
  evidence public.performance_calibration_evidence%ROWTYPE;
  input_count integer;
  minimum_ordinal integer;
  maximum_ordinal integer;
  actual_effort_ids jsonb;
  expected_effort_ids jsonb;
BEGIN
  IF TG_TABLE_NAME = 'performance_calibration_evidence' THEN
    evidence_id_to_validate := NEW.id;
  ELSE
    evidence_id_to_validate := NEW.calibration_evidence_id;
  END IF;
  SELECT * INTO evidence
  FROM public.performance_calibration_evidence
  WHERE id = evidence_id_to_validate;
  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT count(*)::integer,
    min(model_input.ordinal),
    max(model_input.ordinal),
    coalesce(
      jsonb_agg(to_jsonb(model_input.effort_id::text) ORDER BY model_input.ordinal),
      '[]'::jsonb
    )
  INTO input_count, minimum_ordinal, maximum_ordinal, actual_effort_ids
  FROM public.performance_calibration_model_inputs AS model_input
  WHERE model_input.calibration_evidence_id = evidence.id;

  expected_effort_ids := coalesce(
    evidence.diagnostics #> '{model,sourceEvidenceIds}',
    '[]'::jsonb
  );
  IF actual_effort_ids IS DISTINCT FROM expected_effort_ids
    OR (input_count > 0 AND (minimum_ordinal <> 0 OR maximum_ordinal <> input_count - 1))
    OR coalesce((evidence.diagnostics #>> '{model,evidenceCount}')::integer, 0) <> input_count
  THEN
    RAISE EXCEPTION 'calibration model inputs do not match immutable model-run diagnostics'
      USING ERRCODE = '23514',
        CONSTRAINT = 'performance_calibration_model_inputs_complete';
  END IF;
  RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.validate_performance_calibration_selection()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  calibration_id_to_validate uuid;
  calibration public.performance_calibrations%ROWTYPE;
  prior_calibration public.performance_calibrations%ROWTYPE;
  lifecycle_policy jsonb := public.performance_calibration_lifecycle_policy();
  selected_count integer;
  distinct_activity_count integer;
  distinct_day_count integer;
  minimum_ordinal integer;
  maximum_ordinal integer;
  minimum_observed_at timestamptz;
  maximum_observed_at timestamptz;
  minimum_observed_day date;
  maximum_observed_day date;
  minimum_value double precision;
  maximum_value double precision;
  median_value double precision;
  selected_evidence_ids jsonb;
  selected_activity_ids jsonb;
  selection_reason text;
  selection_trend text;
  required_evidence_count integer;
  minimum_day_span integer;
  maximum_day_span integer;
  day_span integer;
  tolerance double precision;
  material_change double precision;
  prior_is_eligible boolean := false;
  current_band_support_exists boolean := false;
  lifecycle_semantics_valid boolean := true;
BEGIN
  IF TG_TABLE_NAME = 'performance_calibrations' THEN
    calibration_id_to_validate := NEW.id;
  ELSE
    calibration_id_to_validate := NEW.calibration_id;
  END IF;
  SELECT * INTO calibration
  FROM public.performance_calibrations
  WHERE id = calibration_id_to_validate;
  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT count(*)::integer,
    count(DISTINCT evidence.activity_id)::integer,
    count(DISTINCT (evidence.observed_at AT TIME ZONE 'UTC')::date)::integer,
    min(link.ordinal),
    max(link.ordinal),
    min(evidence.observed_at),
    max(evidence.observed_at),
    min((evidence.observed_at AT TIME ZONE 'UTC')::date),
    max((evidence.observed_at AT TIME ZONE 'UTC')::date),
    min(evidence.value::double precision),
    max(evidence.value::double precision),
    percentile_cont(0.5) WITHIN GROUP (ORDER BY evidence.value::double precision),
    jsonb_agg(to_jsonb(evidence.id::text) ORDER BY link.ordinal),
    jsonb_agg(to_jsonb(evidence.activity_id::text) ORDER BY link.ordinal)
  INTO selected_count,
    distinct_activity_count,
    distinct_day_count,
    minimum_ordinal,
    maximum_ordinal,
    minimum_observed_at,
    maximum_observed_at,
    minimum_observed_day,
    maximum_observed_day,
    minimum_value,
    maximum_value,
    median_value,
    selected_evidence_ids,
    selected_activity_ids
  FROM public.performance_calibration_selection_evidence AS link
  JOIN public.performance_calibration_evidence AS evidence
    ON evidence.id = link.evidence_id
   AND evidence.profile_id = link.profile_id
   AND evidence.metric_key = link.metric_key
   AND evidence.activity_category = link.activity_category
  WHERE link.calibration_id = calibration.id;

  IF selected_count = 0
    OR minimum_ordinal <> 0
    OR maximum_ordinal <> selected_count - 1
    OR maximum_observed_at IS DISTINCT FROM calibration.effective_at
    OR calibration.selection_diagnostics -> 'selectedEvidenceIds' IS DISTINCT FROM selected_evidence_ids
    OR calibration.selection_diagnostics -> 'selectedActivityIds' IS DISTINCT FROM selected_activity_ids
    OR (calibration.selection_diagnostics ->> 'evidenceCount')::integer IS DISTINCT FROM selected_count
    OR calibration.selection_diagnostics ->> 'policyVersion' IS DISTINCT FROM calibration.policy_version
  THEN
    RAISE EXCEPTION 'calibration selection provenance does not match immutable history'
      USING ERRCODE = '23514',
        CONSTRAINT = 'performance_calibrations_selection_integrity';
  END IF;

  IF calibration.expires_at IS DISTINCT FROM
      calibration.effective_at
        + ((lifecycle_policy ->> 'expiryDays')::integer * INTERVAL '24 hours')
  THEN
    RAISE EXCEPTION 'calibration expiry does not match lifecycle policy'
      USING ERRCODE = '23514',
        CONSTRAINT = 'performance_calibrations_lifecycle_semantics';
  END IF;

  selection_reason := calibration.selection_diagnostics ->> 'selectionReason';
  selection_trend := calibration.selection_diagnostics ->> 'trend';
  day_span := maximum_observed_day - minimum_observed_day;
  tolerance := CASE
    WHEN calibration.metric_key = 'threshold_heart_rate'
      THEN (lifecycle_policy ->> 'heartRateToleranceBpm')::double precision
    ELSE (lifecycle_policy ->> 'relativeTolerance')::double precision
  END;
  material_change := CASE
    WHEN calibration.metric_key = 'threshold_heart_rate'
      THEN (lifecycle_policy ->> 'materialHeartRateChangeBpm')::double precision
    ELSE (lifecycle_policy ->> 'materialRelativeChange')::double precision
  END;

  IF (calibration.selection_diagnostics ->> 'tolerance')::double precision
      IS DISTINCT FROM tolerance
  THEN
    lifecycle_semantics_valid := false;
  END IF;

  IF calibration.supersedes_id IS NOT NULL THEN
    SELECT * INTO prior_calibration
    FROM public.performance_calibrations
    WHERE id = calibration.supersedes_id;

    prior_is_eligible := FOUND
      AND prior_calibration.policy_version = calibration.policy_version
      AND calibration.effective_at >= prior_calibration.effective_at
      AND NOT EXISTS (
        SELECT 1
        FROM public.performance_calibration_selection_evidence AS prior_link
        WHERE prior_link.calibration_id = prior_calibration.id
          AND NOT public.performance_calibration_evidence_is_current(prior_link.evidence_id)
      );
  END IF;

  IF selection_reason = 'first_qualifying_evidence' THEN
    lifecycle_semantics_valid := lifecycle_semantics_valid
      AND selected_count = 1
      AND distinct_activity_count = 1
      AND distinct_day_count = 1
      AND selection_trend = 'initial'
      AND abs(calibration.value::double precision - median_value)
        <= greatest(1e-9, abs(median_value) * 1e-9)
      AND (
        calibration.supersedes_id IS NULL
        OR calibration.effective_at >= prior_calibration.expires_at
        OR NOT prior_is_eligible
      );
  ELSIF selection_reason = 'complete_protocol' THEN
    lifecycle_semantics_valid := lifecycle_semantics_valid
      AND calibration.metric_key = 'threshold_speed'
      AND calibration.activity_category = 'swim'
      AND selected_count = 1
      AND distinct_activity_count = 1
      AND distinct_day_count = 1
      AND selection_trend = 'initial'
      AND abs(calibration.value::double precision - median_value)
        <= greatest(1e-9, abs(median_value) * 1e-9)
      AND (
        calibration.supersedes_id IS NULL
        OR NOT prior_is_eligible
      );
  ELSIF selection_reason = 'independent_confirmation' THEN
    required_evidence_count := (lifecycle_policy #>> '{confirmation,evidenceCount}')::integer;
    minimum_day_span := (lifecycle_policy #>> '{confirmation,minimumDaySpan}')::integer;
    maximum_day_span := (lifecycle_policy #>> '{confirmation,maximumDaySpan}')::integer;
    lifecycle_semantics_valid := lifecycle_semantics_valid
      AND selected_count = required_evidence_count
      AND distinct_activity_count = required_evidence_count
      AND distinct_day_count = required_evidence_count
      AND day_span BETWEEN minimum_day_span AND maximum_day_span
      AND (
        (calibration.metric_key = 'threshold_heart_rate' AND maximum_value - minimum_value <= tolerance)
        OR (calibration.metric_key <> 'threshold_heart_rate' AND maximum_value / minimum_value - 1 <= tolerance)
      )
      AND abs(calibration.value::double precision - median_value)
        <= greatest(1e-9, abs(median_value) * 1e-9)
      AND (
        (calibration.supersedes_id IS NULL AND selection_trend = 'initial')
        OR (
          calibration.supersedes_id IS NOT NULL
          AND (
            (
              NOT prior_is_eligible
              AND selection_trend = 'initial'
            )
            OR (
              prior_is_eligible
              AND selection_trend = 'stable'
              AND (
                (
                  prior_calibration.selection_diagnostics ->> 'selectionReason'
                    = 'first_qualifying_evidence'
                  AND calibration.effective_at < prior_calibration.expires_at
                  AND maximum_observed_at >= prior_calibration.effective_at
                )
                OR (
                  calibration.effective_at >= prior_calibration.expires_at
                  AND minimum_observed_at >= prior_calibration.expires_at
                )
              )
            )
          )
        )
      );
  ELSIF selection_reason IN ('supported_increase', 'supported_decrease', 'unchanged') THEN
    lifecycle_semantics_valid := lifecycle_semantics_valid
      AND calibration.supersedes_id IS NOT NULL
      AND prior_is_eligible
      AND prior_calibration.selection_diagnostics ->> 'selectionReason' <> 'first_qualifying_evidence'
      AND calibration.effective_at < prior_calibration.expires_at
      AND minimum_observed_at >= prior_calibration.effective_at;

    IF selection_reason = 'unchanged' THEN
      required_evidence_count := (lifecycle_policy #>> '{confirmation,evidenceCount}')::integer;
      minimum_day_span := (lifecycle_policy #>> '{confirmation,minimumDaySpan}')::integer;
      maximum_day_span := (lifecycle_policy #>> '{confirmation,maximumDaySpan}')::integer;
      lifecycle_semantics_valid := lifecycle_semantics_valid
        AND selected_count = required_evidence_count
        AND distinct_activity_count = required_evidence_count
        AND distinct_day_count = required_evidence_count
        AND day_span BETWEEN minimum_day_span AND maximum_day_span
        AND selection_trend = 'stable'
        AND calibration.value IS NOT DISTINCT FROM prior_calibration.value
        AND (
          (
            calibration.metric_key = 'threshold_heart_rate'
            AND maximum_value - minimum_value <= tolerance
            AND abs(minimum_value - prior_calibration.value::double precision) <= tolerance
            AND abs(maximum_value - prior_calibration.value::double precision) <= tolerance
          )
          OR (
            calibration.metric_key <> 'threshold_heart_rate'
            AND maximum_value / minimum_value - 1 <= tolerance
            AND abs(minimum_value / prior_calibration.value::double precision - 1) <= tolerance
            AND abs(maximum_value / prior_calibration.value::double precision - 1) <= tolerance
          )
        );
    ELSE
      IF selection_reason = 'supported_increase'
        AND calibration.metric_key <> 'threshold_heart_rate'
      THEN
        required_evidence_count := (lifecycle_policy #>> '{confirmation,evidenceCount}')::integer;
        minimum_day_span := (lifecycle_policy #>> '{confirmation,minimumDaySpan}')::integer;
        maximum_day_span := (lifecycle_policy #>> '{confirmation,maximumDaySpan}')::integer;
      ELSIF selection_reason = 'supported_increase' THEN
        required_evidence_count := (lifecycle_policy #>> '{heartRateChange,evidenceCount}')::integer;
        minimum_day_span := (lifecycle_policy #>> '{heartRateChange,minimumDaySpan}')::integer;
        maximum_day_span := (lifecycle_policy #>> '{heartRateChange,maximumDaySpan}')::integer;
      ELSE
        required_evidence_count := (lifecycle_policy #>> '{decrease,evidenceCount}')::integer;
        minimum_day_span := (lifecycle_policy #>> '{decrease,minimumDaySpan}')::integer;
        maximum_day_span := (lifecycle_policy #>> '{decrease,maximumDaySpan}')::integer;
      END IF;

      lifecycle_semantics_valid := lifecycle_semantics_valid
        AND selected_count = required_evidence_count
        AND distinct_activity_count = required_evidence_count
        AND distinct_day_count = required_evidence_count
        AND day_span BETWEEN minimum_day_span AND maximum_day_span
        AND abs(calibration.value::double precision - median_value)
          <= greatest(1e-9, abs(median_value) * 1e-9)
        AND (
          (calibration.metric_key = 'threshold_heart_rate' AND maximum_value - minimum_value <= tolerance)
          OR (calibration.metric_key <> 'threshold_heart_rate' AND maximum_value / minimum_value - 1 <= tolerance)
        );

      IF selection_reason = 'supported_increase' THEN
        lifecycle_semantics_valid := lifecycle_semantics_valid
          AND selection_trend = 'increasing'
          AND (
            (
              calibration.metric_key = 'threshold_heart_rate'
              AND median_value - prior_calibration.value::double precision >= material_change
            )
            OR (
              calibration.metric_key <> 'threshold_heart_rate'
              AND median_value / prior_calibration.value::double precision - 1 >= material_change
            )
          );
      ELSE
        lifecycle_semantics_valid := lifecycle_semantics_valid
          AND selection_trend = 'decreasing'
          AND (
            (
              calibration.metric_key = 'threshold_heart_rate'
              AND prior_calibration.value::double precision - median_value >= material_change
            )
            OR (
              calibration.metric_key <> 'threshold_heart_rate'
              AND prior_calibration.value::double precision / median_value - 1 >= material_change
            )
          );

        WITH lifecycle_candidates AS (
          SELECT evidence.id,
            evidence.activity_id,
            evidence.observed_at,
            evidence.value::double precision AS value
          FROM public.performance_calibration_evidence AS evidence
          WHERE evidence.profile_id = calibration.profile_id
            AND evidence.metric_key = calibration.metric_key
            AND evidence.activity_category = calibration.activity_category
            AND evidence.policy_version = calibration.policy_version
            AND evidence.observed_at >= prior_calibration.effective_at
            AND evidence.observed_at <= calibration.effective_at
            AND public.performance_calibration_evidence_is_current(evidence.id)
          ORDER BY evidence.observed_at DESC, evidence.id DESC
          LIMIT (lifecycle_policy ->> 'maximumSelectionCandidates')::integer
        )
        SELECT EXISTS (
          SELECT 1
          FROM lifecycle_candidates AS left_evidence
          JOIN lifecycle_candidates AS right_evidence
            ON right_evidence.id > left_evidence.id
           AND right_evidence.activity_id <> left_evidence.activity_id
           AND (right_evidence.observed_at AT TIME ZONE 'UTC')::date
             <> (left_evidence.observed_at AT TIME ZONE 'UTC')::date
          WHERE abs(
              (right_evidence.observed_at AT TIME ZONE 'UTC')::date
              - (left_evidence.observed_at AT TIME ZONE 'UTC')::date
            ) BETWEEN
              (lifecycle_policy #>> '{confirmation,minimumDaySpan}')::integer
              AND (lifecycle_policy #>> '{confirmation,maximumDaySpan}')::integer
            AND (
              (
                calibration.metric_key = 'threshold_heart_rate'
                AND abs(right_evidence.value - left_evidence.value) <= tolerance
                AND abs(right_evidence.value - prior_calibration.value::double precision) <= tolerance
                AND abs(left_evidence.value - prior_calibration.value::double precision) <= tolerance
              )
              OR (
                calibration.metric_key <> 'threshold_heart_rate'
                AND greatest(right_evidence.value, left_evidence.value)
                  / least(right_evidence.value, left_evidence.value) - 1 <= tolerance
                AND abs(right_evidence.value / prior_calibration.value::double precision - 1) <= tolerance
                AND abs(left_evidence.value / prior_calibration.value::double precision - 1) <= tolerance
              )
            )
        ) INTO current_band_support_exists;
        lifecycle_semantics_valid := lifecycle_semantics_valid AND NOT current_band_support_exists;
      END IF;
    END IF;
  ELSE
    lifecycle_semantics_valid := false;
  END IF;

  IF lifecycle_semantics_valid IS NOT TRUE THEN
    RAISE EXCEPTION 'calibration selection violates lifecycle semantics'
      USING ERRCODE = '23514',
        CONSTRAINT = 'performance_calibrations_lifecycle_semantics';
  END IF;
  RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.validate_policy_supersession()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  predecessor_effective_from timestamp with time zone;
BEGIN
  IF NEW.supersedes_policy_version_id IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT effective_from INTO predecessor_effective_from
  FROM public.athlete_consent_policy_versions
  WHERE id = NEW.supersedes_policy_version_id AND scope_key = NEW.scope_key;
  IF predecessor_effective_from IS NULL OR NEW.effective_from < predecessor_effective_from THEN
    RAISE EXCEPTION 'policy supersession must retain scope and cannot move effective chronology backward';
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.withdraw_athlete_consent(p_actor_profile_id uuid, p_organization_id uuid, p_consent_id uuid, p_reason_code text, p_correlation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_now timestamp with time zone := pg_catalog.transaction_timestamp();
  v_organization public.organizations%ROWTYPE;
  v_actor_membership_id uuid;
  v_consent public.athlete_data_sharing_consents%ROWTYPE;
  v_replay_count integer;
  v_matching_replay_count integer;
BEGIN
  IF p_correlation_id IS NULL
    OR p_reason_code IS NULL
    OR p_reason_code !~ '^[a-z0-9][a-z0-9_]{0,63}$' THEN
    RAISE EXCEPTION 'a lowercase reason_code and correlation_id are required';
  END IF;

  SELECT organization.*
  INTO v_organization
  FROM public.organizations AS organization
  WHERE organization.id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found';
  END IF;

  SELECT
    pg_catalog.count(*)::integer,
    pg_catalog.count(*) FILTER (
      WHERE audit.action = 'athlete.consent_withdrawn'
        AND audit.resource_id = p_consent_id
        AND audit.actor_profile_id = p_actor_profile_id
        AND audit.details ->> 'reason_code' = p_reason_code
    )::integer
  INTO v_replay_count, v_matching_replay_count
  FROM public.organization_audit_events AS audit
  WHERE audit.organization_id = p_organization_id
    AND audit.correlation_id = p_correlation_id;

  IF v_replay_count > 0 THEN
    IF v_replay_count = 1 AND v_matching_replay_count = 1 THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'correlation_id conflicts with another terminal request';
  END IF;

  IF v_organization.closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'organization is closed';
  END IF;

  SELECT membership.id
  INTO v_actor_membership_id
  FROM public.organization_memberships AS membership
  WHERE membership.organization_id = p_organization_id
    AND membership.profile_id = p_actor_profile_id
    AND membership.suspended_at IS NULL
    AND membership.ended_at IS NULL
  FOR UPDATE;

  SELECT consent.*
  INTO v_consent
  FROM public.athlete_data_sharing_consents AS consent
  WHERE consent.organization_id = p_organization_id
    AND consent.id = p_consent_id
  FOR UPDATE;

  IF NOT FOUND OR v_consent.athlete_profile_id <> p_actor_profile_id THEN
    RAISE EXCEPTION 'only the exact athlete may withdraw consent';
  END IF;

  IF v_consent.ended_at IS NOT NULL THEN
    RETURN;
  END IF;

  UPDATE public.athlete_data_sharing_consents
  SET ended_at = v_now
  WHERE organization_id = p_organization_id
    AND id = p_consent_id;

  INSERT INTO public.organization_audit_events (
    organization_id,
    actor_profile_id,
    actor_membership_id,
    action,
    resource_type,
    resource_id,
    occurred_at,
    correlation_id,
    details
  ) VALUES (
    p_organization_id,
    p_actor_profile_id,
    v_actor_membership_id,
    'athlete.consent_withdrawn',
    'athlete_data_sharing_consent',
    p_consent_id,
    v_now,
    p_correlation_id,
    pg_catalog.jsonb_build_object('reason_code', p_reason_code)
  );
END
$function$
